2	import crypto from 'node:crypto';
3	import test from 'node:test';
4	import { SnapshotError, Workspace } from '../src/workspace.js';
5	
6	function snapshotOf(documents) {
7	  const workspace = new Workspace();
8	  for (const document of documents) workspace.add(document);
9	  return workspace.exportJSON();
10	}
11	
12	function canonicalChecksum(snapshot) {
13	  return crypto
14	    .createHash('sha256')
15	    .update(JSON.stringify({ version: 1, documents: snapshot.documents }), 'utf8')
16	    .digest('hex');
17	}
18	
19	test('exportJSON uses the fixed key order and canonical checksum', () => {
20	  const snapshot = snapshotOf([
21	    { id: 'welcome', title: '欢迎', body: 'see [[ghost]] for dangling links', tags: ['Intro', 'intro'] },
22	  ]);
23	  const raw = JSON.stringify(snapshot);
24	  assert.match(raw, /^\{"version":1,"documents":\[\{"id"/u);
25	  assert.match(raw, /\],"checksum":"[0-9a-f]{64}"\}$/u);
26	  assert.deepEqual(Object.keys(snapshot), ['version', 'documents', 'checksum']);
27	  assert.deepEqual(Object.keys(snapshot.documents[0]), ['id', 'title', 'body', 'tags']);
28	  assert.equal(snapshot.version, 1);
29	  assert.equal(snapshot.checksum, canonicalChecksum(snapshot));
30	  assert.equal(snapshot.checksum, snapshot.checksum.toLowerCase());
31	});
32	
33	test('exportJSON sorts documents by id code point, unlike list() locale order', () => {
34	  // '.' is U+002E and '_' is U+005F, while localeCompare ranks the underscore first.
35	  const snapshot = snapshotOf([
36	    { id: 'a_b', title: 'Underscore', body: 'body text', tags: [] },
37	    { id: 'a.b', title: 'Dot', body: 'body text', tags: [] },
38	  ]);
39	  assert.deepEqual(snapshot.documents.map((document) => document.id), ['a.b', 'a_b']);
40	});
41	
42	test('exportJSON preserves bodies, tags, and dangling links verbatim', () => {
43	  const snapshot = snapshotOf([
44	    { id: 'note', title: 'Note', body: '[[missing-one]] and [[missing.two]]', tags: ['A', 'b'] },
45	  ]);
46	  assert.equal(snapshot.documents[0].body, '[[missing-one]] and [[missing.two]]');
47	  assert.deepEqual(snapshot.documents[0].tags, ['a', 'b']);
48	});
49	
50	test('exportJSON does not share internal references', () => {
51	  const workspace = new Workspace();
52	  workspace.add({ id: 'note', title: 'Note', body: 'Body', tags: ['tag'] });
53	  const first = workspace.exportJSON();
54	  first.documents[0].title = 'Hijacked';
55	  first.documents[0].tags.push('hijacked');
56	  const second = workspace.exportJSON();
57	  assert.equal(second.documents[0].title, 'Note');
58	  assert.deepEqual(second.documents[0].tags, ['tag']);
59	});
60	
61	test('exportJSON on an empty workspace has a stable checksum', () => {
62	  const snapshot = new Workspace().exportJSON();
63	  assert.deepEqual(snapshot, { version: 1, documents: [], checksum: canonicalChecksum(snapshot) });
64	  assert.deepEqual(new Workspace().exportJSON(), snapshot);
65	});
