function parseMarkdownModeArgs(args, expected) {
  const positionals = [];
  let dryRun = false;
  for (const arg of args) {
    if (arg === '--dry-run') {
      dryRun = true;
    } else if (arg.startsWith('--')) {
      throw new SnapshotError('INVALID_OPTIONS', `unknown option: ${arg}`);
    } else {
      positionals.push(arg);
    }
  }
  if (positionals.length !== expected.length) {
    throw new SnapshotError('INVALID_OPTIONS', `usage: ${expected.usage}`);
  }
  return { positionals, dryRun };
}

function exportMd(args) {
  const { positionals } = parseMarkdownModeArgs(args, {
    length: 2,
    usage: 'export-md <snapshot> <output-directory>',
  });
  const [snapshot, outputDirectory] = positionals;
  const { manifestText } = exportMarkdown(snapshot, outputDirectory);
  process.stdout.write(manifestText);
}

function importMd(args) {
  const { positionals, dryRun } = parseMarkdownModeArgs(args, {
    length: 5,
    usage: 'import-md <base> <input-directory> <output> <mode> [--dry-run]',
  });
  const [base, inputDirectory, output, mode] = positionals;
  if (mode !== 'merge' && mode !== 'replace') {
    throw new SnapshotError('INVALID_OPTIONS', "mode must be 'merge' or 'replace'");
  }
  const { rendered } = importMarkdown(base, inputDirectory, output, mode, dryRun);
  if (dryRun) {
    // The preview is still printed, but no file is created or modified.
    const workspace = new Workspace();
    process.stdout.write(`${JSON.stringify(previewImport(base, inputDirectory, mode))}\n`);
    return;
  }
  process.stdout.write(rendered);
}

// Dry runs share the import's full validation but must not touch the output;
// importMarkdown performs every check before writing, so re-run it in dry mode
// to obtain the projected result snapshot.
function previewImport(base, inputDirectory, mode) {
  // The non-dry call above never runs for --dry-run; this helper exists for
  // readability and delegates to the same validated code path.
  return importMarkdown(base, inputDirectory, null, mode, true).snapshot;
}

